INSERT INTO `page_content` (`page`, `section`, `content`) VALUES
-- About page
('about', 'who_we_are', 'We are a professional visual services studio based in Kundapura, Karnataka. We provide high-quality production and post-production services for individuals, brands, businesses, events, and content creators.\n\nOur expertise includes cinematic shoots, promotional videos, photography projects, and editing services. At Osem Clicks, we don\'t just capture moments—we transform ideas into visually compelling stories.'),

('about', 'our_story', 'Osem Clicks was founded by Keerthan B, beginning as a passion project with a camera and a vision.\n\nOver time, it has grown into a trusted creative studio known for reliability, creativity, and attention to detail.\n\nWe currently provide customized solutions in:\n• Filming\n• Photography\n• Editing\n• Visual content production\n\nCatering to individual creators, small businesses, and large organizations.'),

-- Services page
('services', 'event_shoots', 'Professional photo/video coverage for corporate events, parties, and gatherings. We capture every important moment with precision and creativity.'),

('services', 'product_shoots', 'High-quality product photography & videos for social media, e-commerce, and marketing campaigns. Make your products stand out with professional visuals.'),

('services', 'content_creation', 'Full shooting + editing solutions for content creators (Instagram, YouTube, etc.). From concept to final edit, we\'ve got you covered.'),

('services', 'brand_corporate', 'Visual content for marketing campaigns, product launches, brand promotions, etc. Elevate your brand with professional corporate visuals.'),

('services', 'editing_post', 'Color correction, retouching, highlight reels, montage videos, and complete post-production work. Transform your raw footage into polished masterpieces.'),

('services', 'cinematic', 'Cinematic short films, BTS coverage, and unique storytelling visuals. We bring cinematic quality to your projects.'),

