-- Insert FAQs
INSERT INTO `faqs` (`question`, `answer`, `display_order`) VALUES
('What services do you offer?', 'We offer a comprehensive range of visual services including photography, videography, editing, and post-production for events, products, content creation, brand campaigns, and specialized cinematic projects.', 1),

('Where are you located?', 'We are based in Kundapura, Udupi, Karnataka. However, we are available for shoots across Karnataka and beyond.', 2),

('How do I book a session?', 'You can book a session by filling out our contact form, calling us at +91 63646 20304, or emailing us at osemclicks@gmail.com. We\'ll discuss your requirements and schedule accordingly.', 3),

('What are your rates?', 'Our rates vary depending on the type of service, duration, and specific requirements. Please contact us with your project details for a customized quote.', 4),

('Do you provide editing services only?', 'Yes! We offer standalone editing and post-production services. If you have raw footage or photos that need professional editing, we can help.', 5),

('What equipment do you use?', 'We use professional-grade equipment including the iPhone 15 for mobile photography, along with professional cameras, lenses, stabilizers, and editing software to ensure top-quality results.', 6),

('How long does it take to receive final deliverables?', 'Delivery time depends on the project scope. Typically, edited photos are delivered within 5-7 days, and videos within 10-14 days. Rush delivery options are available upon request.', 7),

('Can I request revisions?', 'Absolutely! We offer revision rounds to ensure you\'re completely satisfied with the final product. The number of revisions depends on the package you choose.', 8);

