-- Insert sample blog posts
INSERT INTO `blogs` (`title`, `cover_image`, `content`, `excerpt`) VALUES
('Welcome to Osem Clicks', 'uploads/blogs/welcome-cover.jpg', 
'<h2>Starting Our Journey</h2><p>Welcome to the official Osem Clicks blog! We\'re excited to share our photography journey, tips, and behind-the-scenes stories with you.</p><p>Photography is more than just clicking pictures—it\'s about capturing emotions, telling stories, and preserving memories. At Osem Clicks, we believe every frame has a story to tell.</p><h3>What to Expect</h3><ul><li>Photography tips and techniques</li><li>Behind-the-scenes from our shoots</li><li>Equipment reviews</li><li>Client success stories</li><li>Industry insights</li></ul><p>Stay tuned for more exciting content!</p>', 
'Welcome to the official Osem Clicks blog! We\'re excited to share our photography journey, tips, and stories with you.'),

('5 Tips for Better Portrait Photography', 'uploads/blogs/portrait-tips-cover.jpg',
'<h2>Master the Art of Portrait Photography</h2><p>Portrait photography is one of the most rewarding genres. Here are 5 essential tips to improve your portrait work:</p><h3>1. Focus on the Eyes</h3><p>The eyes are the window to the soul. Always ensure the eyes are sharp and in focus. This creates an immediate connection between the subject and the viewer.</p><h3>2. Use Natural Light When Possible</h3><p>Natural light can create beautiful, soft portraits. Try shooting during golden hour (sunrise or sunset) for warm, flattering light.</p><h3>3. Mind Your Background</h3><p>A cluttered background distracts from your subject. Look for clean, simple backgrounds or use a wide aperture to blur the background.</p><h3>4. Connect with Your Subject</h3><p>Talk to your subject, make them comfortable, and capture genuine expressions. The best portraits show authentic emotion.</p><h3>5. Experiment with Angles</h3><p>Don\'t just shoot at eye level. Try different angles—shoot from above, below, or from the side to create more dynamic portraits.</p><p>Practice these tips and watch your portrait photography improve dramatically!</p>',
'Master portrait photography with these 5 essential tips for capturing stunning, professional-quality portraits.');
